using System.Text.Json;
using System.Security.Cryptography;
using System.Diagnostics;
using System.Text.RegularExpressions;
namespace Licentivo;
public sealed partial class LicentivoClient {
    private static string OptionalText(JsonElement e,string field)=>e.ValueKind==JsonValueKind.Object&&e.TryGetProperty(field,out var value)?value.GetString()??throw new JsonException("null string"):"";
    private static long OptionalNumber(JsonElement e,string field)=>e.ValueKind==JsonValueKind.Object&&e.TryGetProperty(field,out var value)?value.GetInt64():0;
    private static void VerifyCapabilities(JsonElement c){
        if(c.TryGetProperty("offline_request_id",out var request)&&!Guid.TryParseExact(request.GetString(),"D",out _))throw new CryptographicException("invalid offline request ID");
        if(!c.TryGetProperty("capabilities",out var x))return;
        var allowed=new HashSet<string>{"license_model","session_id","session_expires_at","app_version","version_released_at","maintenance_until","launch_connection_id","environment","binding_version"};if(x.ValueKind!=JsonValueKind.Object||x.EnumerateObject().Any(p=>!allowed.Contains(p.Name)))throw new JsonException("invalid capabilities");
        string model=x.GetProperty("license_model").GetString()!;if(model!="node_locked"&&model!="floating")throw new CryptographicException("invalid license model");
        foreach(string field in new[]{"session_expires_at","version_released_at","maintenance_until"})if(OptionalNumber(x,field)<0||OptionalNumber(x,field)>253402300799L)throw new CryptographicException("invalid entitlement date");
        if(x.TryGetProperty("app_version",out var version)&&!Regex.IsMatch(version.GetString()!,"^(0|[1-9][0-9]{0,8})\\.(0|[1-9][0-9]{0,8})\\.(0|[1-9][0-9]{0,8})$"))throw new CryptographicException("invalid application version");
        long issued=c.GetProperty("issued_at").GetInt64();var policy=Policy(c,issued);
        if(x.TryGetProperty("launch_connection_id",out _)||x.TryGetProperty("environment",out _)||x.TryGetProperty("binding_version",out _)){if(!Guid.TryParseExact(OptionalText(x,"launch_connection_id"),"D",out _)||OptionalText(x,"environment") is not ("live" or "sandbox")||OptionalNumber(x,"binding_version")<1||model!="node_locked"||!Guid.TryParseExact(OptionalText(x,"session_id"),"D",out _)||OptionalNumber(x,"session_expires_at")<=issued||c.GetProperty("expires_at").GetInt64()>OptionalNumber(x,"session_expires_at")||policy.Heartbeat<600||policy.Mode=="permanent"||c.GetProperty("runtime_policy").GetProperty("offline_seconds").GetInt32()>86400)throw new CryptographicException("invalid Launch account session");}
        if(model=="floating"&&(!Guid.TryParseExact(OptionalText(x,"session_id"),"D",out _)||OptionalNumber(x,"session_expires_at")<=issued||c.GetProperty("expires_at").GetInt64()>OptionalNumber(x,"session_expires_at")||!c.TryGetProperty("runtime_policy",out _)||policy.Heartbeat==0||policy.Mode=="permanent"))throw new CryptographicException("invalid floating session");
        if(OptionalNumber(x,"version_released_at")>issued||OptionalNumber(x,"maintenance_until")>0&&(OptionalText(x,"app_version")==""||OptionalNumber(x,"version_released_at")==0||OptionalNumber(x,"version_released_at")>OptionalNumber(x,"maintenance_until")))throw new CryptographicException("invalid maintenance entitlement");
    }
    private void CheckContext(Claims c){if(c.LaunchConnectionId!=config.LaunchConnectionId||c.Environment!=config.Environment)throw new CryptographicException("lease belongs to another Launch connection/environment");if(c.AppVersion!=config.AppVersion||c.LicenseModel=="floating"&&c.SessionId!=sessionID)throw new CryptographicException("lease belongs to another version/session");}
    private Dictionary<string,object> Body(string activation)=>new(){["product_id"]=config.ProductId,["license_key"]=RuntimeKey,["device_id"]=config.DeviceId,["device_name"]=config.DeviceName,["app_version"]=config.AppVersion,["activation_id"]=activation,["session_id"]=sessionID,["device_profile"]=profile};
    private Dictionary<string,object> AccountBody(string activation){var body=Body(activation);if(credential?.LogoutTicket is null)body["request_logout_ticket"]=true;if(config.LaunchConnectionId!=""){body["launch_connection_id"]=config.LaunchConnectionId;body["environment"]=config.Environment;}if(credential?.DeviceKey is not {Length:>0}&&config.IdentityToken!=""){body["identity_token"]=config.IdentityToken;body["launch_connection_id"]=config.LaunchConnectionId;body["environment"]=config.Environment;}return body;}
    public async Task<Claims> Start(Action<Exception>? onError=null,CancellationToken ct=default){ObjectDisposedException.ThrowIf(disposed!=0,this);Claims? result=null;try{result=LocalCheck();if(result.OfflineMode=="none"||result.LicenseModel=="floating")result=null;}catch{}if(result is null){result=await Activate(ct);StartHeartbeat(onError);return result;}StartHeartbeat(onError);if(refreshTask is null||refreshTask.IsCompleted)refreshTask=Task.Run(async()=>{using var linked=CancellationTokenSource.CreateLinkedTokenSource(startupCts.Token,ct);try{await RefreshOnline(linked.Token);}catch(Exception e){if(disposed==0&&onError is not null)_=Task.Run(()=>onError(e));}});return result;}
    public static async Task<LicentivoClient> OpenProduct(string productId,Dictionary<string,string> trustedKeys,string licenseKey,Action<Exception>? onError=null,CancellationToken ct=default){
        var client=new LicentivoClient(new Config("",productId,licenseKey.Trim(),"","",trustedKeys,"",false));
        try{await client.Start(onError,ct);return client;}catch{await client.DisposeAsync();throw;}
    }
    public static async Task<LicentivoClient> Open(string path,Action<Exception>? onError=null,CancellationToken ct=default){var cfg=JsonSerializer.Deserialize<Config>(await File.ReadAllTextAsync(path,ct),JsonOptions)??throw new JsonException("invalid config");var c=new LicentivoClient(cfg);try{await c.Start(onError,ct);return c;}catch{await c.DisposeAsync();throw;}}
    // Shared product settings; the application supplies the customer's license key.
    public static async Task<LicentivoClient> OpenWithLicense(string path,string licenseKey,Action<Exception>? onError=null,CancellationToken ct=default){
        var cfg=JsonSerializer.Deserialize<Config>(await File.ReadAllTextAsync(path,ct),JsonOptions)??throw new JsonException("invalid config");
        cfg=cfg with {LicenseKey=licenseKey.Trim()};
        var c=new LicentivoClient(cfg);
        try{await c.Start(onError,ct);return c;}catch{await c.DisposeAsync();throw;}
    }
    public async Task<JsonElement> Consume(string feature,long quantity,string operationID,CancellationToken ct=default){if(string.IsNullOrEmpty(operationID))throw new ArgumentException("retain operationID for retries");await mutex.WaitAsync(ct);try{var claims=Check();try{return (await Request("consume",claims.ActivationId,ct,operationID,new(){["feature"]=feature,["quantity"]=quantity})).GetProperty("consumption").Clone();}catch(ApiException e){if(new[]{"LICENSE_REVOKED","LICENSE_SUSPENDED","LICENSE_EXPIRED","DEVICE_RELEASED","DEVICE_CREDENTIAL_REVOKED"}.Contains(e.Code))Invalidate();Publish(false,e);throw;}}finally{mutex.Release();}}
    public string OfflineRequest(string operation="activate"){mutex.Wait();try{PrepareCredential();if(operation!="activate"&&operation!="deactivate")throw new ArgumentException("invalid offline operation");string activation="";if(operation=="deactivate"){activation=Check().ActivationId;Invalidate();}var input=AccountBody(activation);input["version"]=1;input["request_id"]=Guid.NewGuid().ToString();input["created_at"]=Now;input["operation"]=operation;return JsonSerializer.Serialize(input,JsonOptions);}finally{mutex.Release();}}
    public Claims ImportOffline(byte[] requestJSON,byte[] responseJSON){mutex.Wait();try{if(signedOut)throw new ApiException(403,"LAUNCH_LOGIN_REQUIRED");using var reqDoc=Parse(requestJSON);using var resDoc=Parse(responseJSON);var req=reqDoc.RootElement;var res=resDoc.RootElement;if(res.GetProperty("version").GetInt32()!=1||req.GetProperty("operation").GetString()!="activate"||res.GetProperty("operation").GetString()!="activate"||req.GetProperty("request_id").GetString()!=res.GetProperty("request_id").GetString()||req.GetProperty("product_id").GetString()!=config.ProductId||req.GetProperty("device_id").GetString()!=config.DeviceId||req.GetProperty("license_key").GetString()!=RuntimeKey)throw new CryptographicException("offline context mismatch");var result=res.GetProperty("result");var envelope=result.GetProperty("lease");var c=Verify(envelope,config.TrustedKeys,config.ProductId,config.DeviceId,Now);CheckContext(c);if(c.OfflineMode=="none"||c.OfflineRequestId!=req.GetProperty("request_id").GetString()||c.ActivationId!=result.GetProperty("activation_id").GetString())throw new CryptographicException("offline signature context mismatch");AcceptCredential(result);cached=envelope.Clone();wall=Now;tick=Stopwatch.GetTimestamp();interval=c.HeartbeatSeconds;Save();Publish(false,null);return c;}finally{mutex.Release();}}
}
